68: /// Tracks how far a forked session's leading events still match the history it
69: /// replayed from its parent.
70: enum CodexReplayState<'a> {
71:     /// Comparing the child's leading usage against the parent's usage prefix.
72:     MatchingParent {
73:         prefix: &'a [CodexRawUsage],
74:         index: usize,
75:     },
76:     /// The parent stream could not anchor the replay, so skip the leading burst
77:     /// that Codex rewrote to the fork instant. Carries the last skipped event so
78:     /// the run can be followed however long it takes to write.
79:     SkippingRewrittenBurst(TimestampMs),
80:     /// Past the replayed history: every remaining event is the child's own usage.
81:     Done,
82: }
83: 
84: /// Longest pause tolerated inside a burst of replayed usage.
85: ///
86: /// Codex rewrites a replayed history to the fork instant and writes it in one
87: /// go, so the burst is dense while the child's own first turn follows a real
88: /// pause. Across the fork logs this was measured against, bursts spanned 10 to
89: /// 40ms and the pause that followed ran from 5.8 to 15.3 seconds, so a second
90: /// sits two orders of magnitude above the one and well below the other.
91: ///
92: /// Bucketing by the recorded second instead would split any burst written across
93: /// a second tick, leaving the remainder counted as the child's own usage.
94: const CODEX_REWRITTEN_BURST_PAUSE_MS: i64 = 1_000;
