99: /// history it did not spend; one that pauses between them was recording its own
100: /// turns from the start.
101: fn detect_rewritten_burst(path: &Path) -> Option<TimestampMs> {
102:     let Ok(file) = fs::File::open(path) else {
103:         return None;
104:     };
105:     let mut reader = BufReader::new(file);
106:     let mut line = Vec::new();
107:     let mut first: Option<TimestampMs> = None;
108: 
109:     loop {
110:         line.clear();
111:         let Ok(bytes_read) = reader.read_until(b'\n', &mut line) else {
112:             return None;
113:         };
114:         if bytes_read == 0 {
115:             return None;
116:         }
117:         let Some(CodexLineKind::Session) = codex_line_usage_kind(&line) else {
118:             continue;
119:         };
120:         let Ok(value) = serde_json::from_slice::<CodexSessionLogEntry<'_>>(&line) else {
121:             continue;
122:         };
123:         let info = value.payload.as_ref().and_then(|payload| {
124:             (value.entry_type.as_deref() == Some("event_msg")
125:                 && payload.payload_type.as_deref() == Some("token_count"))
126:             .then_some(payload.info.as_ref())
127:             .flatten()
128:         });
129:         if info
130:             .is_none_or(|info| info.last_token_usage.is_none() && info.total_token_usage.is_none())
131:         {
132:             continue;
133:         }
134:         let Some(timestamp) = codex_session_timestamp(value.timestamp.as_ref())
135:             .as_deref()
136:             .and_then(parse_ts_timestamp)
137:         else {
138:             continue;
139:         };
140:         match first {
141:             None => first = Some(timestamp),
142:             Some(first) => {
143:                 return (0..=CODEX_REWRITTEN_BURST_PAUSE_MS)
144:                     .contains(&(timestamp.as_millis() - first.as_millis()))
145:                     .then_some(first);
