205:                             CodexReplayState::SkippingRewrittenBurst,
206:                         );
207:                 }
208:                 CodexReplayState::SkippingRewrittenBurst(previous) => {
209:                     if let Some(timestamp) = parse_ts_timestamp(&event.timestamp)
210:                         && (0..=CODEX_REWRITTEN_BURST_PAUSE_MS)
211:                             .contains(&(timestamp.as_millis() - previous.as_millis()))
