276: fn visit_codex_session_entry(
277:     session_id: &str,
278:     value: CodexSessionLogEntry<'_>,
279:     previous_totals: &mut Option<CodexRawUsage>,
280:     current_model: &mut Option<String>,
281:     current_model_is_fallback: &mut bool,
282:     current_service_tier: &mut Option<CodexServiceTier>,
283:     visit: &mut impl FnMut(CodexTokenUsageEvent) -> Result<()>,
284: ) -> Result<()> {
285:     let entry_type = value.entry_type.as_deref();
286:     if entry_type == Some("turn_context") {
287:         if let Some(model) = value.payload.as_ref().and_then(codex_model_from_payload) {
288:             *current_model = Some(model);
289:             *current_model_is_fallback = false;
290:         }
291:         return Ok(());
292:     }
293:     if entry_type != Some("event_msg") {
294:         return Ok(());
295:     }
296:     let Some(timestamp) = codex_session_timestamp(value.timestamp.as_ref()) else {
297:         return Ok(());
298:     };
299:     let Some(payload) = value.payload.as_ref() else {
300:         return Ok(());
301:     };
302:     if payload.payload_type.as_deref() == Some("thread_settings_applied") {
303:         // A settings event that carries no `service_tier` at all says nothing
304:         // about the tier, so the previous one stands. Codex emits such events
305:         // for auto-review threads. A tier that is present but unrecognized is
306:         // different: it means the tier changed to something unknown, so the
307:         // stale value must not be inherited.
308:         if let Some(recorded) = payload
309:             .thread_settings
310:             .as_ref()
311:             .and_then(|settings| settings.service_tier.as_deref())
312:         {
313:             *current_service_tier = codex_service_tier(recorded);
314:         }
315:         return Ok(());
316:     }
317:     if payload.payload_type.as_deref() != Some("token_count") {
318:         return Ok(());
319:     }
320:     let info = payload.info.as_ref();
321:     let total_usage = info.and_then(|info| info.total_token_usage.as_ref().copied());
322:     let cumulative_advanced = total_usage
323:         .as_ref()
324:         .is_none_or(|total_usage| previous_totals.as_ref() != Some(total_usage));
325:     let raw_usage = info
326:         .and_then(|info| info.last_token_usage.as_ref().copied())
327:         .filter(|_| cumulative_advanced)
328:         .or_else(|| {
329:             total_usage
330:                 .as_ref()
331:                 .map(|usage| subtract_codex_raw_usage(usage, previous_totals.as_ref()))
332:         });
333:     if let Some(total_usage) = total_usage {
334:         *previous_totals = Some(total_usage);
335:     }
336:     let Some(raw_usage) = raw_usage else {
337:         return Ok(());
338:     };
339:     if raw_usage.input_tokens == 0
340:         && raw_usage.cached_input_tokens == 0
341:         && raw_usage.output_tokens == 0
342:         && raw_usage.reasoning_output_tokens == 0
343:     {
344:         return Ok(());
345:     }
346: 
347:     let parsed_model =
348:         codex_model_from_payload(payload).or_else(|| info.and_then(codex_model_from_info));
349:     let (model, is_fallback_model) = resolve_codex_usage_model(
350:         parsed_model,
351:         &timestamp,
352:         current_model,
353:         current_model_is_fallback,
354:     );
355: 
356:     visit(CodexTokenUsageEvent {
357:         session_id: session_id.to_string(),
358:         timestamp,
359:         model,
360:         input_tokens: raw_usage.input_tokens,
361:         cached_input_tokens: raw_usage.cached_input_tokens.min(raw_usage.input_tokens),
362:         output_tokens: raw_usage.output_tokens,
363:         reasoning_output_tokens: raw_usage.reasoning_output_tokens,
364:         total_tokens: raw_usage.total_tokens,
365:         is_fallback_model,
366:         service_tier: *current_service_tier,
367:     })
368: }
