459: fn codex_service_tier(value: &str) -> Option<CodexServiceTier> {
460:     match value {
461:         // Both spellings mean non-priority pricing and occur in the same Codex
462:         // version on the same day; which one is written depends on the client
463:         // (Codex Desktop writes "standard"), not on the CLI version.
464:         "default" | "standard" => Some(CodexServiceTier::Standard),
465:         "fast" | "priority" => Some(CodexServiceTier::Fast),
466:         _ => None,
467:     }
