470: fn codex_line_usage_kind(line: &[u8]) -> Option<CodexLineKind> {
471:     let has_event_msg = EVENT_MSG_TYPE_FINDER.find(line).is_some();
472:     let has_token_count = has_event_msg && TOKEN_COUNT_TYPE_FINDER.find(line).is_some();
473:     let has_thread_settings_applied =
474:         has_event_msg && THREAD_SETTINGS_APPLIED_TYPE_FINDER.find(line).is_some();
475:     if TURN_CONTEXT_TYPE_FINDER.find(line).is_some()
476:         || has_token_count
477:         || has_thread_settings_applied
478:     {
479:         return Some(CodexLineKind::Session);
480:     }
481:     let has_compact_type = COMPACT_TYPE_FIELD_FINDER.find(line).is_some();
482:     let has_nested_token_count = !has_event_msg
483:         && has_compact_type
484:         && line.len() < 64 * 1024
485:         && TOKEN_COUNT_TYPE_FINDER.find(line).is_some();
486:     let has_nested_thread_settings_applied = !has_event_msg
487:         && has_compact_type
488:         && line.len() < 64 * 1024
489:         && THREAD_SETTINGS_APPLIED_FINDER.find(line).is_some();
490:     if has_event_msg
491:         || has_nested_token_count
492:         || has_nested_thread_settings_applied
493:         || !has_compact_type
494:     {
495:         let (has_turn_context, has_event_msg, has_token_count, has_thread_settings_applied) =
496:             codex_line_type_flags(line);
497:         if has_turn_context || (has_event_msg && (has_token_count || has_thread_settings_applied)) {
498:             return Some(CodexLineKind::Session);
499:         }
500:     }
501:     if USAGE_FIELD_FINDER.find(line).is_some()
502:         || INPUT_TOKENS_FIELD_FINDER.find(line).is_some()
503:         || PROMPT_TOKENS_FIELD_FINDER.find(line).is_some()
504:     {
505:         return Some(CodexLineKind::Headless);
506:     }
507:     None
508: }
509: 
510: fn codex_line_type_flags(line: &[u8]) -> (bool, bool, bool, bool) {
511:     let mut start = 0;
512:     let mut has_turn_context = false;
513:     let mut has_event_msg = false;
514:     let mut has_token_count = false;
515:     let mut has_thread_settings_applied = false;
516:     while let Some(index) = TYPE_KEY_FINDER.find(&line[start..]) {
517:         let key_start = start + index;
518:         let mut cursor = skip_json_whitespace(line, key_start + br#""type""#.len());
519:         if line.get(cursor) != Some(&b':') {
520:             start = key_start + br#""type""#.len();
521:             continue;
522:         }
523:         cursor = skip_json_whitespace(line, cursor + 1);
524:         if line.get(cursor) != Some(&b'"') {
525:             start = cursor.saturating_add(1);
526:             continue;
527:         }
528:         cursor += 1;
529:         has_turn_context |= json_string_value_matches(line, cursor, b"turn_context");
530:         has_event_msg |= json_string_value_matches(line, cursor, b"event_msg");
531:         has_token_count |= json_string_value_matches(line, cursor, b"token_count");
532:         has_thread_settings_applied |=
533:             json_string_value_matches(line, cursor, b"thread_settings_applied");
534:         if has_turn_context || (has_event_msg && (has_token_count || has_thread_settings_applied)) {
535:             return (
536:                 has_turn_context,
537:                 has_event_msg,
538:                 has_token_count,
539:                 has_thread_settings_applied,
540:             );
541:         }
542:         start = cursor.saturating_add(1);
543:     }
544:     (
545:         has_turn_context,
546:         has_event_msg,
547:         has_token_count,
548:         has_thread_settings_applied,
549:     )
550: }
551: 
552: fn json_string_value_matches(line: &[u8], start: usize, value: &[u8]) -> bool {
553:     line.get(start..start + value.len())
554:         .is_some_and(|candidate| candidate == value)
555:         && line.get(start + value.len()) == Some(&b'"')
556: }
557: 
558: fn skip_json_whitespace(line: &[u8], mut index: usize) -> usize {
559:     while matches!(line.get(index), Some(b' ' | b'\n' | b'\r' | b'\t')) {
560:         index += 1;
561:     }
562:     index
563: }
