575: fn parsed_model_is_missing(
576:     model: &Option<String>,
577:     current_model: &Option<String>,
578:     current_model_is_fallback: bool,
579: ) -> bool {
580:     model.is_some() && current_model.is_some() && current_model_is_fallback
581: }
