583: fn resolve_codex_usage_model(
584:     parsed_model: Option<String>,
585:     timestamp: &str,
586:     current_model: &mut Option<String>,
587:     current_model_is_fallback: &mut bool,
588: ) -> (Option<String>, bool) {
589:     if let Some(model) = parsed_model.as_ref() {
590:         *current_model = Some(model.clone());
591:         *current_model_is_fallback = false;
592:     }
593:     let mut is_fallback_model = false;
594:     let model = parsed_model.or_else(|| current_model.clone()).or_else(|| {
595:         is_fallback_model = true;
596:         *current_model_is_fallback = true;
597:         *current_model = Some("gpt-5".to_string());
598:         current_model.clone()
599:     });
600:     if parsed_model_is_missing(&model, current_model, *current_model_is_fallback) {
601:         is_fallback_model = true;
602:     }
603:     let model = model.map(|model| {
604:         codex_log_model_fallback(&model, timestamp)
605:             .map(|fallback| {
606:                 is_fallback_model = true;
607:                 fallback.to_string()
608:             })
609:             .unwrap_or(model)
610:     });
611:     (model, is_fallback_model)
612: }
613: 
614: fn codex_log_model_fallback(model: &str, timestamp: &str) -> Option<&'static str> {
615:     if model != CODEX_AUTO_REVIEW_MODEL {
616:         return None;
617:     }
618:     let Some(date) = codex_timestamp_date(timestamp) else {
619:         return Some("gpt-5");
620:     };
621:     Some(
622:         codex_auto_review_fallback_models()
623:             .iter()
624:             .find_map(|fallback| (date >= fallback.released_on).then_some(fallback.model))
625:             .unwrap_or("gpt-5"),
626:     )
627: }
628: 
629: fn codex_auto_review_fallback_models() -> &'static [CodexAutoReviewFallback<'static>] {
630:     CODEX_AUTO_REVIEW_FALLBACK_MODELS.as_slice()
631: }
632: 
633: fn codex_timestamp_date(timestamp: &str) -> Option<&str> {
634:     let date = timestamp.get(..10)?;
635:     let bytes = date.as_bytes();
636:     if !(bytes.len() == 10
637:         && bytes[0..4].iter().all(u8::is_ascii_digit)
638:         && bytes[4] == b'-'
639:         && bytes[5..7].iter().all(u8::is_ascii_digit)
640:         && bytes[7] == b'-'
641:         && bytes[8..10].iter().all(u8::is_ascii_digit))
642:     {
643:         return None;
644:     }
645:     let year = codex_date_part(&bytes[0..4])?;
646:     let month = codex_date_part(&bytes[5..7])?;
647:     let day = codex_date_part(&bytes[8..10])?;
648:     let max_day = codex_days_in_month(year, month)?;
649:     (day >= 1 && day <= max_day).then_some(date)
650: }
651: 
652: fn codex_date_part(bytes: &[u8]) -> Option<u16> {
653:     bytes.iter().try_fold(0u16, |value, byte| {
654:         let digit = byte.checked_sub(b'0')?;
655:         (digit <= 9).then_some(value * 10 + u16::from(digit))
656:     })
657: }
658: 
659: fn codex_days_in_month(year: u16, month: u16) -> Option<u16> {
660:     match month {
661:         1 | 3 | 5 | 7 | 8 | 10 | 12 => Some(31),
662:         4 | 6 | 9 | 11 => Some(30),
663:         2 if codex_is_leap_year(year) => Some(29),
664:         2 => Some(28),
665:         _ => None,
666:     }
667: }
668: 
669: fn codex_is_leap_year(year: u16) -> bool {
670:     year.is_multiple_of(4) && !year.is_multiple_of(100) || year.is_multiple_of(400)
671: }
