676:         .with_extension("")
677:         .components()
678:         .filter_map(|component| component.as_os_str().to_str())
679:         .collect::<Vec<_>>()
680:         .join("/");
681:     if session_id.is_empty() {
682:         session_id = "unknown".to_string();
683:     }
684:     session_id
685: }
