633: fn codex_timestamp_date(timestamp: &str) -> Option<&str> {
634:     let date = timestamp.get(..10)?;
635:     let bytes = date.as_bytes();
636:     if !(bytes.len() == 10
637:         && bytes[0..4].iter().all(u8::is_ascii_digit)
638:         && bytes[4] == b'-'
639:         && bytes[5..7].iter().all(u8::is_ascii_digit)
640:         && bytes[7] == b'-'
641:         && bytes[8..10].iter().all(u8::is_ascii_digit))
642:     {
643:         return None;
644:     }
645:     let year = codex_date_part(&bytes[0..4])?;
646:     let month = codex_date_part(&bytes[5..7])?;
647:     let day = codex_date_part(&bytes[8..10])?;
648:     let max_day = codex_days_in_month(year, month)?;
649:     (day >= 1 && day <= max_day).then_some(date)
650: }
651: 
652: fn codex_date_part(bytes: &[u8]) -> Option<u16> {
653:     bytes.iter().try_fold(0u16, |value, byte| {
654:         let digit = byte.checked_sub(b'0')?;
655:         (digit <= 9).then_some(value * 10 + u16::from(digit))
656:     })
657: }
