659: fn codex_days_in_month(year: u16, month: u16) -> Option<u16> {
660:     match month {
661:         1 | 3 | 5 | 7 | 8 | 10 | 12 => Some(31),
662:         4 | 6 | 9 | 11 => Some(30),
663:         2 if codex_is_leap_year(year) => Some(29),
664:         2 => Some(28),
665:         _ => None,
666:     }
667: }
