552: fn json_string_value_matches(line: &[u8], start: usize, value: &[u8]) -> bool {
553:     line.get(start..start + value.len())
554:         .is_some_and(|candidate| candidate == value)
555:         && line.get(start + value.len()) == Some(&b'"')
556: }
557: 
558: fn skip_json_whitespace(line: &[u8], mut index: usize) -> usize {
559:     while matches!(line.get(index), Some(b' ' | b'\n' | b'\r' | b'\t')) {
560:         index += 1;
561:     }
562:     index
563: }
